balanced_policy:
table inet mwan3 {
	chain mwan3_policy_balanced {
		meta mark & 0x3f000000 == 0x00000000 numgen random mod 3 vmap { 0 : jump mwan3_or_meta_0x1000000, 1 : jump mwan3_or_meta_0x2000000, 2 : jump mwan3_or_meta_0x3000000 }
		meta mark & 0x3f000000 == 0x00000000 meta mark set meta mark & 0xfeffffff | 0x3e000000
	}
}

ua3f_policy:
table inet mwan3 {
	chain mwan3_policy_ua3f_bal {
		meta mark & 0x3f000000 == 0x00000000 numgen inc mod 3 vmap { 0 : jump mwan3_or_meta_0x1000000, 1 : jump mwan3_or_meta_0x2000000, 2 : jump mwan3_or_meta_0x3000000 }
		meta mark & 0x3f000000 == 0x00000000 meta mark set meta mark & 0xfeffffff | 0x3e000000
	}
}

ttl:
table inet fw4 {
	chain ua3f_wan_ttl {
		type filter hook postrouting priority -150; policy accept;
		oifname "wan" ip ttl >= 10 counter packets 140488 bytes 40684642 ip ttl set 64 comment "WAN IPv4 TTL64"
		oifname "eswan2" ip ttl >= 10 counter packets 207340 bytes 46008349 ip ttl set 64 comment "WAN2 IPv4 TTL64"
		oifname "eswan3" ip ttl >= 10 counter packets 38668 bytes 7270847 ip ttl set 64 comment "WAN3 IPv4 TTL64"
	}
}
